int minCut(char *s) {
  int n = (int)strlen(s);
  if (n <= 1) return 0;

  int **pal = (int **)malloc(sizeof(int *) * n);
  for (int i = 0; i < n; i++) {
    pal[i] = (int *)calloc(n, sizeof(int));
  }
  for (int i = n - 1; i >= 0; i--) {
    for (int j = i; j < n; j++) {
      if (s[i] == s[j] && (j - i < 2 || pal[i + 1][j - 1])) {
        pal[i][j] = 1;
      }
    }
  }

  int *dp = (int *)malloc(sizeof(int) * n);
  for (int i = 0; i < n; i++) {
    if (pal[0][i]) {
      dp[i] = 0;
      continue;
    }
    dp[i] = i;
    for (int j = 1; j <= i; j++) {
      if (pal[j][i] && dp[j - 1] + 1 < dp[i]) {
        dp[i] = dp[j - 1] + 1;
      }
    }
  }

  int res = dp[n - 1];
  free(dp);
  for (int i = 0; i < n; i++) free(pal[i]);
  free(pal);
  return res;
}

class Solution {
public:
  int minCut(string s) {
    int n = s.size();
    if (n <= 1) return 0;

    vector<vector<bool>> pal(n, vector<bool>(n, false));
    for (int i = n - 1; i >= 0; i--) {
      for (int j = i; j < n; j++) {
        if (s[i] == s[j] && (j - i < 2 || pal[i + 1][j - 1])) {
          pal[i][j] = true;
        }
      }
    }

    vector<int> dp(n, 0);
    for (int i = 0; i < n; i++) {
      if (pal[0][i]) {
        dp[i] = 0;
        continue;
      }
      dp[i] = i;
      for (int j = 1; j <= i; j++) {
        if (pal[j][i]) {
          dp[i] = min(dp[i], dp[j - 1] + 1);
        }
      }
    }
    return dp[n - 1];
  }
};

